from robyn import Robyn, WebSocket
import json

app = Robyn(__file__)
ws = WebSocket(app, "/ws/telemetry/:stream_id")

ACTIVE_STREAMS = {}

@ws.on_connect
async def on_connect(ws_connection, request):
    stream_id = request.path_params.get("stream_id")
    token = request.headers.get("Sec-WebSocket-Protocol", "")
    user = verify_jwt_token(token)
    if not user:
        return ws_connection.close(1008)

    if not stream_belongs_to_tenant(stream_id, user.tenant_id):
        return ws_connection.close(1008)

    if stream_id not in ACTIVE_STREAMS:
        ACTIVE_STREAMS[stream_id] = []
    ACTIVE_STREAMS[stream_id].append(ws_connection)
